namespace sv_429c40319fc947a885d77ad95dc10f20.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_429c40319fc947a885d77ad95dc10f20.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul>
        @foreach (var section in Sections)
        {
            <li class="@(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
                @section
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };
}

@namespace sv_429c40319fc947a885d77ad95dc10f20.Components.Pages.Settings
@using sv_429c40319fc947a885d77ad95dc10f20.Services

<div class="settings-section">
    <h2>Profile</h2>

    @if (_profile is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="avatar-preview">
            <img src="@_displayName" alt="Avatar" style="display:none;" />
            <div class="avatar-placeholder">Avatar Preview</div>
            <p class="avatar-url">@_avatarUrl</p>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="_displayName" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="_email" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="_bio" rows="4"></textarea>
        </div>

        <div class="form-actions">
            <button class="btn-primary" @onclick="SaveChanges">Save Changes</button>
            <button class="btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Profile saved successfully!</div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        LoadFromProfile(_profile);
    }

    private void LoadFromProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void DiscardChanges()
    {
        if (_profile is not null)
        {
            LoadFromProfile(_profile);
        }
    }
}

@namespace sv_429c40319fc947a885d77ad95dc10f20.Components.Pages.Settings
@using sv_429c40319fc947a885d77ad95dc10f20.Services

<div class="settings-section">
    <h2>Notifications</h2>

    @if (_prefs is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_emailNotifications" />
                <span>Email Notifications</span>
            </label>

            <label class="toggle-label">
                <input type="checkbox" @bind="_pushNotifications" />
                <span>Push Notifications</span>
            </label>

            <label class="toggle-label">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span>Weekly Digest</span>
            </label>
        </div>

        <h3>Muted Channels</h3>
        <div class="channel-list">
            @foreach (var channel in _allChannels)
            {
                <label class="toggle-label">
                    <input type="checkbox"
                           checked="@_mutedChannels.Contains(channel)"
                           @onchange="e => ToggleMuteChannel(channel, (bool)e.Value!)" />
                    <span>@channel</span>
                </label>
            }
        </div>

        <div class="form-actions">
            <button class="btn-primary" @onclick="SavePreferences">Save Preferences</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Preferences saved!</div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();

    private static readonly string[] _allChannels = { "General", "Updates", "Marketing", "Engineering", "Support" };

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = _prefs.EmailNotifications;
        _pushNotifications = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(_prefs.MutedChannels);
    }

    private void ToggleMuteChannel(string channel, bool isMuted)
    {
        if (isMuted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _prefs = updated;
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private bool _showSuccess;

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_429c40319fc947a885d77ad95dc10f20.Components.Pages.Settings
@using sv_429c40319fc947a885d77ad95dc10f20.Services

<div class="settings-section">
    <h2>Security</h2>

    @if (_settings is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>Change Password</span>
                <span class="chevron">@(_passwordPanelOpen ? "▲" : "▼")</span>
            </button>

            @if (_passwordPanelOpen)
            {
                <div class="panel-content">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="_currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="_newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(_passwordError))
                    {
                        <div class="error-message">@_passwordError</div>
                    }
                    @if (_passwordSuccess)
                    {
                        <div class="toast success">Password updated successfully!</div>
                    }
                    <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="tfa-section">
            <label class="toggle-label">
                <input type="checkbox" checked="@_settings.TwoFactorEnabled" disabled />
                <span>Two-Factor Authentication</span>
                <span class="status-indicator @(_settings.TwoFactorEnabled ? "enabled" : "disabled")">
                    @(_settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </label>
            @if (_settings.LastPasswordChange.HasValue)
            {
                <p class="last-changed">Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <h3>Active Sessions</h3>
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in _settings.Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session != _settings.Sessions.FirstOrDefault())
                            {
                                <button class="btn-danger" @onclick="() => ConfirmRevoke(session)">Revoke</button>
                            }
                            else
                            {
                                <span class="current-session">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>

        <!-- Revoke Confirmation Dialog -->
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-overlay">
                <div class="modal-dialog">
                    <h4>Confirm Session Revocation</h4>
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                    <div class="modal-actions">
                        <button class="btn-danger" @onclick="RevokeSession">Revoke</button>
                        <button class="btn-secondary" @onclick="() => _sessionToRevoke = null">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public ISettingsService SettingsService { get; set; } = default!;

    private SecuritySettings? _settings;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private bool _passwordSuccess;
    private ActiveSession? _sessionToRevoke;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task UpdatePassword()
    {
        _passwordError = null;
        _passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password is required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _passwordSuccess = true;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _settings = await SettingsService.GetSecuritySettingsAsync();
            _sessionToRevoke = null;
        }
    }
}

@namespace sv_429c40319fc947a885d77ad95dc10f20.Components.Pages.Settings
@using sv_429c40319fc947a885d77ad95dc10f20.Services

<div class="settings-section">
    <h2>Appearance</h2>

    @if (_settings is null)
    {
        <p>Loading...</p>
    }
    else
    {
        <!-- Theme Selector -->
        <div class="form-group">
            <label>Theme</label>
            <div class="radio-group">
                <label><input type="radio" name="theme" value="Light" checked="@(_theme == "Light")" @onchange="() => _theme = &quot;Light&quot;" /> Light</label>
                <label><input type="radio" name="theme" value="Dark" checked="@(_theme == "Dark")" @onchange="() => _theme = &quot;Dark&quot;" /> Dark</label>
                <label><input type="radio" name="theme" value="System" checked="@(_theme == "System")" @onchange="() => _theme = &quot;System&quot;" /> System</label>
            </div>
        </div>

