arguments.file_text:
@page "/settings"
@using sv_429c40319fc947a885d77ad95dc10f20.Services
@using sv_429c40319fc947a885d77ad95dc10f20.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection SettingsService="SettingsService" />
                break;
            case "Notifications":
                <NotificationsSection SettingsService="SettingsService" />
                break;
            case "Security":
                <SecuritySection SettingsService="SettingsService" />
                break;
            case "Appearance":
                <AppearanceSection SettingsService="SettingsService" />
                break;
        }
    </main>
</div>

@code {
    [Inject] public ISettingsService SettingsService { get; set; } = default!;

    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

.settings-dashboard {
    display: flex;
    min-height: 80vh;
    gap: 2rem;
    padding: 1rem;
}

/* Sidebar */
.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
    min-width: 180px;
}

.settings-sidebar li {
    padding: 0.75rem 1rem;
    cursor: pointer;
    border-radius: 6px;
    margin-bottom: 0.25rem;
    transition: background-color 0.2s;
}

.settings-sidebar li:hover {
    background-color: #f0f0f0;
}

.settings-sidebar li.active {
    background-color: #0d6efd;
    color: #fff;
    font-weight: 600;
}

/* Main content area */
.settings-content {
    flex: 1;
    max-width: 720px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid #dee2e6;
}

/* Form elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.5rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
}

.form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

/* Buttons */
.btn-primary {
    background-color: #0d6efd;
    color: #fff;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary:hover {
    background-color: #0b5ed7;
}

.btn-secondary {
    background-color: #6c757d;
    color: #fff;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-danger {
    background-color: #dc3545;
    color: #fff;
    border: none;
    padding: 0.35rem 0.75rem;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.85rem;
}

/* Toggle labels */
.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.5rem;
    cursor: pointer;
}

.toggle-group {
    margin-bottom: 1.5rem;
}

/* Toast messages */
.toast.success {
    background-color: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-top: 1rem;
}

/* Avatar preview */
.avatar-preview {
    margin-bottom: 1.5rem;
    padding: 1rem;
    border: 1px dashed #ced4da;
    border-radius: 8px;
    text-align: center;
}

.avatar-placeholder {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background-color: #e9ecef;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    color: #6c757d;
}

.avatar-url {
    font-size: 0.8rem;
    color: #6c757d;
    margin-top: 0.5rem;
    word-break: break-all;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #dee2e6;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
    border-radius: 6px;
}

.panel-content {
    padding: 1rem;
    border-top: 1px solid #dee2e6;
}

/* Status indicator */
.status-indicator {
    font-size: 0.8rem;
    padding: 0.2rem 0.5rem;
    border-radius: 12px;
}

.status-indicator.enabled {
    background-color: #d1e7dd;
    color: #0f5132;
}

.status-indicator.disabled {
    background-color: #f8d7da;
    color: #842029;
}

.tfa-section {
    margin-bottom: 1.5rem;
}

.last-changed {
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 1.5rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    border-bottom: 1px solid #dee2e6;
    text-align: left;
}

.sessions-table th {
    background-color: #f8f9fa;
    font-weight: 600;
}

.current-session {
    font-size: 0.8rem;
    color: #6c757d;
    font-style: italic;
}

/* Modal */
.modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    padding: 1.5rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1rem;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.25rem;
    margin-top: 0.25rem;
}

.radio-group label {
    display: flex;
    align-items: center;
    gap: 0.3rem;
    cursor: pointer;
    font-weight: normal;
}

/* Channel list */
.channel-list {
    margin-bottom: 1.5rem;
    padding-left: 0.5rem;
}

/* Live preview */
.live-preview {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 1.5rem;
    margin-top: 1.5rem;
    margin-bottom: 1rem;
    transition: all 0.3s;
}

.live-preview h4 {
    margin-top: 0;
}

.preview-theme-dark {
    background-color: #1a1a2e;
    color: #e0e0e0;
}

.preview-theme-dark .btn-primary {
    background-color: #4dabf7;
}

.preview-theme-light {
    background-color: #ffffff;
    color: #212529;
}

.preview-theme-system {
    background-color: #f8f9fa;
    color: #212529;
}

.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

.preview-compact {
    padding: 0.75rem;
    line-height: 1.2;
}

/* Error message */
.error-message {
    color: #dc3545;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

